from datetime import datetime

class User:
    def __init__(self, username, email, date_of_birth):
        self.username = username
        self.email = email
        self.date_of_birth = parse_date(date_of_birth)

def parse_date(date_str):
    try:
        return datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        raise ValueError("Invalid date format. Please use YYYY-MM-DD.")

def validate_signup(signup_form):
    if len(signup_form['username']) < 6:
        return "Username must be at least 6 characters long."
    if not signup_form['email'].endswith('@example.com'):
        return "Email must be from example.com."
    if signup_form['date_of_birth'] < datetime(1900, 1, 1):
        return "Invalid date of birth. Please enter a date after 1900."
    return None
```

